from datetime import date, timedelta
import calendar

WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
WEEKDAY_NAMES = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]


def _nth_weekday(year, month, wd, n):
    days = [d for d in range(1, calendar.monthrange(year, month)[1] + 1)
            if date(year, month, d).weekday() == wd]
    if n == -1:
        return days[-1] if days else None
    return days[n - 1] if 0 < n <= len(days) else None


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    K = int(parts[1])
    out = []
    limit = date(2999, 12, 31)

    if kind == "DAILY":
        d = s
        while len(out) < count:
            if d > limit:
                break
            out.append(d.isoformat())
            d += timedelta(days=K)

    elif kind == "WEEKLY":
        days = sorted({WEEKDAYS[x] for x in parts[3].split(",")})
        week0_mon = s - timedelta(days=s.weekday())
        w = 0
        while len(out) < count:
            wk_start = week0_mon + timedelta(weeks=w * K)
            if wk_start > limit + timedelta(days=6):
                break
            for wd in days:
                d = wk_start + timedelta(days=wd)
                if d >= s and d <= limit:
                    out.append(d.isoformat())
            if len(out) >= count:
                break
            w += 1
        out.sort()
        out = out[:count]

    elif kind == "MONTHLY":
        if len(parts) == 3:
            d_val = int(parts[2])
            mi = 0
            while len(out) < count:
                total = s.year * 12 + (s.month - 1) + mi * K
                y, m = divmod(total, 12)
                m += 1
                if date(y, m, 1) > limit:
                    break
                if d_val == -1:
                    day = calendar.monthrange(y, m)[1]
                elif d_val <= calendar.monthrange(y, m)[1]:
                    day = d_val
                else:
                    day = None
                if day is not None:
                    d = date(y, m, day)
                    if d >= s and d <= limit:
                        out.append(d.isoformat())
                mi += 1
        else:
            n = int(parts[2])
            wd = WEEKDAYS[parts[3]]
            mi = 0
            while len(out) < count:
                total = s.year * 12 + (s.month - 1) + mi * K
                y, m = divmod(total, 12)
                m += 1
                if date(y, m, 1) > limit:
                    break
                day = _nth_weekday(y, m, wd, n)
                if day is not None:
                    d = date(y, m, day)
                    if d >= s and d <= limit:
                        out.append(d.isoformat())
                mi += 1

    elif kind == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        yi = 0
        while len(out) < count:
            y = s.year + yi * K
            if y > 2999:
                break
            try:
                d = date(y, mm, dd)
            except ValueError:
                d = None
            if d is not None and d >= s:
                out.append(d.isoformat())
            yi += 1

    return out[:count]
